// Darstellungskomponente: kennt weder Service noch Router
@Component({
  selector: 'customer-filter',
  template: `
    <input [value]="value()"
           (input)="changed.emit($any($event.target).value)">
  `
})
export class CustomerFilterComponent {
  value = input('');            // Eingang: aktueller Filtertext
  changed = output<string>();   // Ausgang: neuer Text nach einer Eingabe
}

@if (draft(); as c) {
  <form #customerForm="ngForm">
    <input name="firstname" [(ngModel)]="c.firstname">
    <input name="city" [(ngModel)]="c.city">

    <p>Formular: {{ customerForm.valid ? 'gültig' : 'ungültig' }}</p>
  </form>
}
<!-- c: bearbeitbare Kopie des Kunden, das Original bleibt unverändert -->
<!-- #customerForm="ngForm": Zugriff auf das ganze Formular, z. B. .valid -->

// Der geladene Kunde (nur lesen!)
customer = computed(() => {
  const id = this.id();
  return id ? this.customerService.getById(id) : undefined;
});

// Bearbeitbare Kopie: folgt dem Original, kann aber überschrieben werden
draft = linkedSignal(() => {
  const customer = this.customer();
  return customer ? { ...customer } : undefined;
});
// Wechselt customer (z. B. andere ID), entsteht draft neu aus dem Original
